static SlugCell *sv_cell_new(void){ SlugCell *c=(SlugCell*)sv_heap_alloc(sizeof(SlugCell),SH_CELL);c->permanent_root=false;c->heap_owned=true;c->value=sv_null();sv_scope_track(c);return c; }
